from __future__ import annotations

from waiting_phone_models import WaitingRoomPhoneError, WaitingTicket


def collect_arrival_ranks(tickets: list[WaitingTicket]) -> list[int]:
    return [t.arrival_rank for t in tickets]


def assert_unique_arrival_ranks(tickets: list[WaitingTicket]) -> None:
    ranks = collect_arrival_ranks(tickets)
    if len(ranks) != len(set(ranks)):
        raise WaitingRoomPhoneError("duplicate arrival_rank in meeting snapshot")


def assert_non_empty_queue(tickets: list[WaitingTicket]) -> None:
    if not tickets:
        raise WaitingRoomPhoneError("empty waiting-room snapshot")


def rank_spread(tickets: list[WaitingTicket]) -> int:
    if not tickets:
        return 0
    ranks = collect_arrival_ranks(tickets)
    return max(ranks) - min(ranks)


def is_dense_ranking(tickets: list[WaitingTicket]) -> bool:
    if not tickets:
        return True
    ranks = sorted(collect_arrival_ranks(tickets))
    return ranks == list(range(ranks[0], ranks[0] + len(ranks)))


def arrival_index_for_ticket(tickets: list[WaitingTicket], ticket_id: str) -> int:
    for idx, t in enumerate(sorted(tickets, key=lambda x: (x.arrival_rank, x.ticket_id))):
        if t.ticket_id == ticket_id:
            return idx
    raise WaitingRoomPhoneError("ticket not in snapshot")


def explain_rank_policy() -> str:
    return "fifo_by_arrival_rank_then_ticket_id"


def coalesce_bridge_optional_tail(primary: str, secondary: str) -> str:
    p = str(primary).strip()
    s = str(secondary).strip()
    return p if p else s


def gate_rank_bounds(tickets: list[WaitingTicket], ceiling: int) -> bool:
    return all(t.arrival_rank <= ceiling for t in tickets)


def meeting_scope_label(meeting_id: str, revision: int) -> str:
    mid = str(meeting_id).strip()
    if not mid:
        raise WaitingRoomPhoneError("meeting_id required")
    if revision < 0:
        raise WaitingRoomPhoneError("revision must be non-negative")
    return f"{mid}:rev{revision}"


def ticket_channel_priority_stub(bridge_connected: bool) -> int:
    return 1 if bridge_connected else 0


def compare_waiters_by_fifo(a: WaitingTicket, b: WaitingTicket) -> int:
    if a.arrival_rank < b.arrival_rank:
        return -1
    if a.arrival_rank > b.arrival_rank:
        return 1
    if a.ticket_id < b.ticket_id:
        return -1
    if a.ticket_id > b.ticket_id:
        return 1
    return 0


def format_rank_diagnostic(tickets: list[WaitingTicket]) -> str:
    ordered = sorted(tickets, key=lambda t: (t.arrival_rank, t.ticket_id))
    return ",".join(str(t.arrival_rank) for t in ordered)


def clone_rank_list(tickets: list[WaitingTicket]) -> list[int]:
    return list(collect_arrival_ranks(tickets))


def freeze_ticketing_policy_version() -> str:
    return "waiting-room-phone-v1"

