from __future__ import annotations

from waiting_phone_models import WaitingTicket, count_bridged, count_voip_only, describe_queue_pressures
from waiting_room_bridge import bridge_depth, project_admit_queue, queue_integrity_hint


def summarize_waiting_snapshot(tickets: list[WaitingTicket]) -> dict[str, object]:
    order = project_admit_queue(tickets)
    ranks = [next(t.arrival_rank for t in tickets if t.ticket_id == tid) for tid in order]
    return {
        "admit_order": order,
        "headcount": len(tickets),
        "bridged_legs": count_bridged(tickets),
        "voip_only": count_voip_only(tickets),
        "bridge_connected_layers": bridge_depth(tickets),
        "rank_trace": ranks,
        "integrity_hint": queue_integrity_hint(tickets),
        "pressure": describe_queue_pressures(tickets),
    }


def audit_fifo_matches_rank_order(summary: dict[str, object]) -> bool:
    ranks: list[int] = list(summary["rank_trace"])
    return ranks == sorted(ranks)


def headline_from_summary(summary: dict[str, object]) -> str:
    return f"n={summary['headcount']};pstn={summary['bridged_legs']}"


def bridged_ratio(summary: dict[str, object]) -> float:
    hc = int(summary["headcount"])
    if hc == 0:
        return 0.0
    return round(float(summary["bridged_legs"]) / hc, 3)


def compare_admit_to_true_fifo(summary: dict[str, object], true_order: list[str]) -> bool:
    return list(summary["admit_order"]) == true_order


def export_support_lines(summary: dict[str, object]) -> list[str]:
    lines: list[str] = []
    for idx, tid in enumerate(summary["admit_order"]):
        lines.append(f"{idx}:{tid}")
    return lines


def snapshot_serial_stub(meeting_id: str, revision: int) -> str:
    mid = str(meeting_id).strip()
    if not mid:
        raise ValueError("meeting_id required")
    return f"{mid}#{revision}"


def empty_snapshot_summary() -> dict[str, object]:
    return summarize_waiting_snapshot([])


def trace_has_duplicate_ranks(summary: dict[str, object]) -> bool:
    r = list(summary["rank_trace"])
    return len(r) != len(set(r))


def rank_order_is_sorted(summary: dict[str, object]) -> bool:
    r = list(summary["rank_trace"])
    return r == sorted(r)


def admit_head(summary: dict[str, object]) -> str | None:
    order = list(summary["admit_order"])
    return order[0] if order else None


def support_pack(summary: dict[str, object]) -> str:
    return f"{summary['pressure']};order={summary['admit_order']}"


def voip_majority(summary: dict[str, object]) -> bool:
    return int(summary["voip_only"]) > int(summary["bridged_legs"])


def bridge_penetration_warning(summary: dict[str, object]) -> str:
    ratio = bridged_ratio(summary)
    if ratio >= 0.5:
        return "heavy_pstn"
    if ratio > 0:
        return "mixed"
    return "voice_only"


def ledger_revision_hint(revision: int) -> str:
    return f"waiting-snapshot-r{revision}"


def compare_headcounts(summary: dict[str, object], expected: int) -> bool:
    return int(summary["headcount"]) == expected

