from __future__ import annotations

from dataclasses import dataclass


class WaitingRoomPhoneError(ValueError):
    """Invalid ticket or telephony merge payload."""


def _non_empty(label: str, value: str) -> str:
    token = str(value).strip()
    if not token:
        raise WaitingRoomPhoneError(f"{label} required")
    return token


@dataclass
class WaitingTicket:
    """One waiting-room occupant; bridge flags are updated in place after PSTN merge."""

    ticket_id: str
    arrival_rank: int
    bridge_connected: bool = False
    phone_e164_tail: str = ""

    def __post_init__(self) -> None:
        tid = _non_empty("ticket_id", self.ticket_id)
        if self.arrival_rank < 0:
            raise WaitingRoomPhoneError("arrival_rank must be non-negative")
        self.ticket_id = tid

    def attach_bridge(self, e164_tail: str) -> None:
        tail = _non_empty("phone_e164_tail", e164_tail)
        self.bridge_connected = True
        self.phone_e164_tail = tail

    def bridge_label(self) -> str:
        if not self.bridge_connected:
            return "voip"
        return f"pstn:{self.phone_e164_tail}"


@dataclass(frozen=True)
class BridgeMergeSignal:
    ticket_id: str
    phone_e164_tail: str
    merge_seq: int = 0

    def __post_init__(self) -> None:
        _non_empty("ticket_id", self.ticket_id)
        _non_empty("phone_e164_tail", self.phone_e164_tail)
        if self.merge_seq < 0:
            raise WaitingRoomPhoneError("merge_seq must be non-negative")


def ticket_row_label(ticket: WaitingTicket) -> str:
    return f"{ticket.ticket_id}@{ticket.arrival_rank}"


def tickets_by_id_map(tickets: list[WaitingTicket]) -> dict[str, WaitingTicket]:
    out: dict[str, WaitingTicket] = {}
    for t in tickets:
        if t.ticket_id in out:
            raise WaitingRoomPhoneError("duplicate ticket_id in batch")
        out[t.ticket_id] = t
    return out


def count_bridged(tickets: list[WaitingTicket]) -> int:
    return sum(1 for t in tickets if t.bridge_connected)


def count_voip_only(tickets: list[WaitingTicket]) -> int:
    return sum(1 for t in tickets if not t.bridge_connected)


def ticket_fingerprint(ticket: WaitingTicket) -> str:
    return f"{ticket.ticket_id}:{ticket.arrival_rank}:{ticket.bridge_label()}"


def merge_signal_fingerprint(sig: BridgeMergeSignal) -> str:
    return f"{sig.ticket_id}:{sig.phone_e164_tail}:{sig.merge_seq}"


def describe_queue_pressures(tickets: list[WaitingTicket]) -> str:
    return f"n={len(tickets)} bridged={count_bridged(tickets)}"


def sort_ticket_refs_stable(tickets: list[WaitingTicket]) -> list[WaitingTicket]:
    return sorted(tickets, key=lambda t: (t.arrival_rank, t.ticket_id))


def ticket_meeting_scope_stub(meeting_id: str, ticket: WaitingTicket) -> str:
    mid = _non_empty("meeting_id", meeting_id)
    return f"{mid}|{ticket.ticket_id}"


def ensure_unique_ticket_ids(tickets: list[WaitingTicket]) -> None:
    seen: set[str] = set()
    for t in tickets:
        if t.ticket_id in seen:
            raise WaitingRoomPhoneError("duplicate ticket_id")
        seen.add(t.ticket_id)


def strip_tail_suffix_digits(tail: str) -> str:
    return "".join(ch for ch in tail if ch.isdigit())

