from __future__ import annotations

from arrival_policy import (
    assert_unique_arrival_ranks,
    explain_rank_policy,
    format_rank_diagnostic,
)
from waiting_phone_models import BridgeMergeSignal, WaitingTicket, WaitingRoomPhoneError, tickets_by_id_map


def apply_bridge_merge(tickets: list[WaitingTicket], signal: BridgeMergeSignal) -> None:
    for ticket in tickets:
        if ticket.ticket_id != signal.ticket_id:
            continue
        if ticket.bridge_connected:
            return
        ticket.attach_bridge(signal.phone_e164_tail)
        return
    raise ValueError("unknown ticket_id for bridge merge")


def project_admit_queue(tickets: list[WaitingTicket]) -> list[str]:
    if not tickets:
        return []
    try:
        assert_unique_arrival_ranks(tickets)
    except WaitingRoomPhoneError as exc:
        raise ValueError(str(exc)) from exc

    def sort_key(t: WaitingTicket) -> tuple[str | int, ...]:
        # Starter bug: once PSTN legs connect, support asked for "alphabetical phone polish"
        # that accidentally destabilizes FIFO between bridged waiters.
        dial = t.phone_e164_tail if t.bridge_connected else "000000"
        return (dial, t.arrival_rank, t.ticket_id)

    ordered = sorted(tickets, key=sort_key)
    return [t.ticket_id for t in ordered]


def replay_merges(tickets: list[WaitingTicket], signals: list[BridgeMergeSignal]) -> None:
    for sig in signals:
        apply_bridge_merge(tickets, sig)


def admit_preview_line(tickets: list[WaitingTicket]) -> str:
    ids = project_admit_queue(tickets)
    return ">>".join(ids)


def queue_integrity_hint(tickets: list[WaitingTicket]) -> str:
    return f"ranks={format_rank_diagnostic(tickets)};policy={explain_rank_policy()}"


def export_rank_vector(tickets: list[WaitingTicket]) -> list[int]:
    order = project_admit_queue(tickets)
    by_id = tickets_by_id_map(tickets)
    return [by_id[i].arrival_rank for i in order]


def merge_count_for_meeting(signals: list[BridgeMergeSignal]) -> int:
    return len(signals)


def bridge_depth(tickets: list[WaitingTicket]) -> int:
    return sum(1 for t in tickets if t.bridge_connected)


def fifo_candidate_order(tickets: list[WaitingTicket]) -> list[str]:
    return [t.ticket_id for t in sorted(tickets, key=lambda x: (x.arrival_rank, x.ticket_id))]


def meeting_ticket_digest(tickets: list[WaitingTicket]) -> str:
    return ":".join(fifo_candidate_order(tickets))


def signal_targets_ticket(signal: BridgeMergeSignal, ticket: WaitingTicket) -> bool:
    return signal.ticket_id == ticket.ticket_id


def meeting_scope_label_stub(meeting_id: str, ticket_count: int) -> str:
    mid = str(meeting_id).strip()
    if not mid:
        raise ValueError("meeting_id required")
    return f"{mid}|t={ticket_count}"

